    if (token.Kind == kind) {
      cc_gen++;
      if (++cc_gc > 100) {
        cc_gc = 0;
        for (int i = 0; i < cc_2_rtns.Length; i++) {
          CCCalls c = cc_2_rtns[i];
          while (c != null) {
            if (c.gen < cc_gen) c.first = null;
            c = c.next;
          }
        }
      }
      return token;
    }
    token = oldToken;
    cc_kind = kind;
    throw GenerateParseException();
  }

