    } else if (cc_endpos != 0) {
      cc_expentry = new int[cc_endpos];
      for (int i = 0; i < cc_endpos; i++) {
        cc_expentry[i] = cc_lasttokens[i];
      }
      bool exists = false;
      foreach (int[] oldentry in cc_expentries) {
        if (oldentry.Length != cc_expentry.Length) continue;
        exists = true;
        for (int i = 0; i < cc_expentry.Length; i++) {
          if (oldentry[i] != cc_expentry[i]) { exists = false; break; }
        }
        if (exists) break;
      }
      if (!exists) cc_expentries.Add(cc_expentry);
      if (pos != 0) cc_lasttokens[(cc_endpos = pos) - 1] = kind;
    }
  }

